def transform(grid):
    h = len(grid)
    w = len(grid[0])
    # The divider is the column dominated by one repeated non-zero color.
    candidates = []
    for c in range(w):
        counts = {}
        for r in range(h):
            value = grid[r][c]
            if value:
                counts[value] = counts.get(value, 0) + 1
        if counts:
            candidates.append((max(counts.values()), c))
    div = max(candidates)[1]
    out = [row[:] for row in grid]
    for r in range(h):
        left = grid[r][:div]
        runs = []
        i = div - 1
        while i >= 0:
            color = left[i]
            if color == 0:
                i -= 1
                continue
            j = i
            while j >= 0 and left[j] == color:
                j -= 1
            runs.append((color, i - j))
            i = j
        for x in range(w - div - 1):
            value = 0
            for color, period in reversed(runs):
                if x % period == 0:
                    value = color
            out[r][div + 1 + x] = value
    return out
